-- Referensi agenda organisasi Malang Timur, Oktober-November 2026.
-- Tidak menciptakan presensi, jurnal, target, status terlaksana, atau kewajiban kehadiran.
create table if not exists public.simpul_schedule_reference (
 code text primary key,
 title text not null,
 event_date date not null,
 organizer_level text not null check (organizer_level in ('PUSAT','DAERAH','DESA','KELOMPOK','UMUM')),
 start_local time without time zone,
 end_local time without time zone,
 location text,
 details text,
 created_at timestamptz not null default now()
);
create index if not exists simpul_schedule_reference_month_idx on public.simpul_schedule_reference(event_date);
alter table public.simpul_schedule_reference enable row level security;
drop policy if exists "read_reference_schedule" on public.simpul_schedule_reference;
create policy "read_reference_schedule" on public.simpul_schedule_reference for select to anon,authenticated using (true);
revoke all on public.simpul_schedule_reference from anon,authenticated;
grant select (code,title,event_date,organizer_level,start_local,end_local,location,details) on public.simpul_schedule_reference to anon,authenticated;
on conflict (code) do update set title=excluded.title,event_date=excluded.event_date,organizer_level=excluded.organizer_level,start_local=excluded.start_local,end_local=excluded.end_local,location=excluded.location,details=excluded.details;
